const restructureFeedbackComponentId = React.useMemo(() => {
    const raw: any = restructureSelectedItems[0]?.raw || selectedFlatRows[0]?.original || checkedList;
    if (!raw) return undefined;
    const itemType = String(raw.Item_x0020_Type || '');
    if (itemType === 'Component' || itemType === 'Project') {
        return raw.Id ?? raw.ID;
    }
    return raw.Portfolio?.Id ?? raw.PortfolioId ?? raw.Id ?? raw.ID;
}, [restructureSelectedItems, checkedList]);

