    if (smartAllFilterData?.length > 0 && updatedSmartFilter === false) {
        isColumnDefultSortingAsc = false
        hasCustomExpanded = true
        hasExpanded = true
        isHeaderNotAvlable = false
        setLoaded(false);
        componentData = [];
        AfterFilterTaskCount = [];
        let count = 0;
        let afterFilter = true;
        let smartAllFilterBackup: any = []
        try {
            for (let i = 0; i < smartAllFilterData.length; i += 5000) {
                smartAllFilterBackup.push(...globalCommon.deepCopy(smartAllFilterData?.slice(i, i + 5000)));
            }
        } catch (error) {
            devSuccess("backup Json parse error backGround Loade All Task Data")
        }
        setAllSmartFilterDataBackup(smartAllFilterBackup);
        if (isUpdated === "") {
            portfolioTypeData?.map((port: any, index: any) => {
                count = count + 1;
                componentGrouping(port?.Id, index);
            })
        } else if (isUpdated.length) {
            portfolioTypeData?.map((port: any) => {
                if (isUpdated.toLowerCase() === port?.Title?.toLowerCase()) {
                    count = count + 1;
                    componentGrouping(port?.Id, '');
                }
            })
        }
        taskTypeDataItem?.filter((taskLevelcount: any) => { taskLevelcount[taskLevelcount.Title + 'filterNumber'] = 0 });
        AfterFilterTaskCount = AfterFilterTaskCount?.filter((ele: any, ind: any, arr: any) => {
            const isDuplicate = arr.findIndex((elem: any) => { return (elem.ID === ele.ID || elem.Id === ele.Id) && elem.siteType === ele.siteType; }) !== ind
            return !isDuplicate;
        })
        countTaskAWTLevel(AfterFilterTaskCount, afterFilter);
        childRef?.current?.setRowSelection({});
        childRef?.current?.setColumnFilters([]);
        childRef?.current?.setGlobalFilter('');
    }
    if (smartAllFilterData?.length > 0 && updatedSmartFilter === true && updatedSmartFilterFlatView === false) {
        isColumnDefultSortingAsc = false
        hasCustomExpanded = true
        hasExpanded = true
        isHeaderNotAvlable = false
        setLoaded(false);
        filterCount = 0;
        componentDataCopyBackup = [];
        setDataBackup([]);
        let AllSmartFilterDataBackups: any = []
        try {
            for (let i = 0; i < smartAllFilterData.length; i += 5000) {
                AllSmartFilterDataBackups.push(...globalCommon.deepCopy(AllSmartFilterDataBackup?.slice(i, i + 5000)));
            }
        } catch (error) {
            devSuccess("backup Json parse error backGround Loade All Task Data")
        }

        setDataBackup(AllSmartFilterDataBackups);
        let componentDatas: any = []
        try {
            for (let i = 0; i < smartAllFilterData.length; i += 5000) {
                componentDatas.push(...globalCommon.deepCopy(componentData?.slice(i, i + 5000)));
            }
        } catch (error) {
            devSuccess("backup Json parse error backGround Loade All Task Data")
        }
        componentDataCopyBackup = componentDatas
        // Superman: Step 4 — refine now rebuilds through componentGrouping,
        // the same reusable pipeline Clear Filters already uses (proven
        // byte-identical in Step 1, and verified against real production
        // data via the Step 3 comparison harness across multiple filter
        // combinations — all MATCH). filterDataAfterUpdate/
        // updatedSmartFilterGrouping (the old prune-from-backup path) are
        // left fully in place, just no longer called from here — kept for
        // rollback until this cutover is confirmed solid in real use.
        // Selection / column filters / global filter are intentionally
        // left untouched here, same as before — Clear Filters resets them,
        // refining preserves them.
        let count = 0;
        let afterFilter = true;
        componentData = [];
        AfterFilterTaskCount = [];
        if (isUpdated === "") {
            portfolioTypeData?.map((port: any, index: any) => {
                count = count + 1;
                componentGrouping(port?.Id, index);
            })
        } else if (isUpdated.length) {
            portfolioTypeData?.map((port: any) => {
                if (isUpdated.toLowerCase() === port?.Title?.toLowerCase()) {
                    count = count + 1;
                    componentGrouping(port?.Id, '');
                }
            })
        }
        taskTypeDataItem?.filter((taskLevelcount: any) => { taskLevelcount[taskLevelcount.Title + 'filterNumber'] = 0 });
        countTaskAWTLevel(smartAllFilterData, afterFilter)
        portfolioTypeDataItem?.filter((taskLevelcount: any) => { taskLevelcount[taskLevelcount.Title + 'filterNumber'] = 0 });
        countComponentLevel(smartAllFilterData, afterFilter)
    } else if (smartAllFilterData?.length > 0 && updatedSmartFilter === true && updatedSmartFilterFlatView === true) {
        let afterFilter = true;
        taskTypeDataItem?.filter((taskLevelcount: any) => { taskLevelcount[taskLevelcount.Title + 'filterNumber'] = 0 });
        countTaskAWTLevel(smartAllFilterData, afterFilter)
        portfolioTypeDataItem?.filter((taskLevelcount: any) => { taskLevelcount[taskLevelcount.Title + 'filterNumber'] = 0 });
        countComponentLevel(smartAllFilterData, afterFilter)
        setLoaded(true);
        updatedSmartFilterFlatViewData(smartAllFilterData);
    }
}, [smartAllFilterData]);
